    public void appendKeyVal_FailedEncodingTest() throws UnsupportedEncodingException {
        UrlBuilder urlBuilder = new UrlBuilder("http://example.com");
        assertEquals([], urlBuilder.appendKeyVal(new String[][]{{"key", "value"}}));
